  u57: {
    id: "u57", no: 57, day: 7, part: "practical", pages: "169–171", minutes: 16,
    title: "الحبليات — الأرنب",
    titleEn: "Chordates — The Rabbit",
    summary: "الأرنب نموذج الثدييات، يُخدر بالكلوروفورم ويُوضع على ظهره في لوح التشريح. جهازه الهضمي يشمل المعدة والأمعاء واللفائفي والكيبي المستدير والأعور والزائدة الدودية والقولون والمستقيم، ويلحق به الكبد والبنكرياس والغدد اللعابية.",
    blocks: [
      { t: "h", x: "الشكل الخارجي" },
      { t: "ul", items: [
        "الجسم مغطى بالفراء، وينقسم إلى رأس ورقبة وجذع وطرفين وأذنين طويلتين وذيل قصير.",
        "العيون جانبية وذات أجفان، والأنف رطب، والفم بأسنان متغايرة التسنين، والفتحات التناسلية والإست منفصلة."
      ] },
      { t: "h", x: "خطوات التشريح" },
      { t: "ul", items: [
        "يُخدر الأرنب بالكلوروفورم، ويُوضع على ظهره على لوح التشريح ويُثبت بأطرافه.",
        "تُرفع القشرة والجلد في منتصف البطن، ثم يُقص جدار البطن بعناية لتجنب إتلاف الأحشاء.",
        "تفحص الغدد اللعابية والمرىء والمعدة والأمعاء، ثم الكبد والمرارة والبنكرياس والطحال والكليتين والمثانة."
      ] },
      { t: "h", x: "الجهاز الهضمي" },
      { t: "ul", items: [
        "المعدة ثم الاثنا عشري والصائم، ثم اللفائفي وهو قناة بها تحززات كثيرة، ويقع الكيس الكروي (الكيبي المستدير).",
        "يمتد من الأعور الزائدة الدودية ثم القولون والمستقيم، وينتهي بفتحة الشرج.",
        "يلحق بالجهاز الهضمي الكبد (أكبر غدة هضمية) والمرارة والبنكرياس والغدد اللعابية، والطحال ملحق بالدورة الدموية."
      ] },
      { t: "img", src: "figures/p169_0.png", cap: "الأرنب — الشكل الخارجي" },
      { t: "img", src: "figures/p170_0.png", cap: "الجهاز الهضمي للأرنب" },
      { t: "img", src: "figures/p171_0.png", cap: "خطوات تشريح الأرنب" },
      { t: "note", x: "الأعور والزائدة الدودية والكيبي المستدير من أبرز ما يميز جهاز الأرنب الهضمي في العملي." }
    ],
    terms: [
      { ar: "اللفائفي", en: "Ileum", def: "الجزء الأخير من الأمعاء الدقيقة بتحززات كثيرة." },
      { ar: "الأعور", en: "Caecum", def: "كيس كبير عند بداية القولون." },
      { ar: "الزائدة الدودية", en: "Appendix", def: "زائد دودي ينتهي به الأعور." },
      { ar: "الكيبي المستدير", en: "Sacculus rotundus", def: "كيس كروي عند نهاية اللفائفي." }
    ],
    quiz: [
      { q: "يُخدر الأرنب في التشريح بـ:", o: ["الماء", "الكلوروفورم", "الملح", "الصبغة"], a: 1, e: "بالكلوروفورم." },
      { q: "الأمعاء الدقيقة تنتهي بـ:", o: ["القولون", "اللفائفي", "المستقيم", "المعدة"], a: 1, e: "اللفائفي ثم الأعور." },
      { q: "الزائدة الدودية تخرج من:", o: ["المعدة", "الأعور", "الكبد", "المثانة"], a: 1, e: "من الأعور." },
      { q: "أكبر غدة هضمية في الأرنب:", o: ["البنكرياس", "الكبد", "الغدة اللعابية", "المرارة"], a: 1, e: "الكبد." }
    ]
  }


